def analyze(name):
    gi,go=G[name+' input'],G[name+' output']
    cnt=Counter(x for r in gi for x in r); bgc=max(cnt,key=lambda c:cnt[c])
    others=[c for c in cnt if c!=bgc]; accent=max(others,key=lambda c:cnt[c])
    H,W=len(gi),len(gi[0])
    ac={(r,c) for r in range(H) for c in range(W) if gi[r][c]==accent}
    res=[]
    for i in range(H):
        for j in range(W):
            if gi[i][j]!=bgc: continue
            dirs=[]
            for dn,dj in DIRS:
                r,c=i+dn,j+dj; hit=False; stop=False
                while 0<=r<H and 0<=c<W:
                    if (r,c) in ac: hit=True; break
                    if gi[r][c]!=bgc: stop=True; break
                    r+=dn;c+=dj
                if stop: dirs.append('N')  # noise before accent or no accent
                elif hit: dirs.append('A')
                else: dirs.append('-')   # edge
            to=go[i][j]
            res.append((name,i,j,to,tuple(dirs)))
    return bgc,accent,res
