def between(gi,i,j,accent):
    H,W=len(gi),len(gi[0])
    for dn,dj in DIRS[:8]:
        def clearstep(dn2,dj2,r,c):
            while 0<=r<H and 0<=c<W:
                if gi[r][c]==accent: return 'A'
                if gi[r][c]!=bgc: return 'N'
                r+=dn2;c+=dj2
            return '-'
        fwd=clearstep(dn,dj,i+dn,j+dj)
        bwd=clearstep(-dn,-dj,i-dn,j-dj)
        if fwd=='A' and bwd=='A': return True
    return False
