def seglen(i,j,gi,accent,bgc,dirv):
    dn,dj=dirv
    H,W=len(gi),len(gi[0])
    r,c=i+dn,j+dj;n=1
    while 0<=r<H and 0<=c<W and gi[r][c]==bgc: n+=1; r+=dn;c+=dj
    fwd=(0<=r<H and 0<=c<W and gi[r][c]==accent)
    r,c=i-dn,j-dj;n2=1
    while 0<=r<H and 0<=c<W and gi[r][c]==bgc: n2+=1; r-=dn;c-=dj
    bwd=(0<=r<H and 0<=c<W and gi[r][c]==accent)
    return fwd and bwd, n+n2
