def gaps(gi,i,j,accent,bgc):
    H,W=len(gi),len(gi[0])
    res=[]
    for dn,dj in DIRS:
        # forward gap
        r,c=i+dn,j+dj; gf=None
        while 0<=r<H and 0<=c<W:
            if gi[r][c]==accent: gf=r-i//dn if dn else None; break
            if gi[r][c]!=bgc: gf=-1; break
            r+=dn;c+=dj
        bwd=None
        r,c=i-dn,j-dj
        while 0<=r<H and 0<=c<W:
            if gi[r][c]==accent: bwd=i-(r) ; break
            if gi[r][c]!=bgc: bwd=-1; break
            r-=dn;c-=dj
        if gf>=0 and bwd>=0: res.append((gf,bwd))
    return res
