def gapdist(gi,i,j,accent,bgc):
    H,W=len(gi),len(gi[0])
    res=[]
    for dn,dj in DIRS:
        r,c=i+dn,j+dj; gf=None
        while 0<=r<H and 0<=c<W:
            if gi[r][c]==accent: gf=r-i; break
            if gi[r][c]!=bgc: gf=None; break
            r+=dn;c+=dj
        r2,c2=i-dn,j-dj; bw=None
        while 0<=r2<H and 0<=c2<W:
            if gi[r2][c2]==accent: bw=i-r2; break
            if gi[r2][c2]!=bgc: bw=None; break
            r2-=dn;c2-=dj
        if gf is not None and bw is not None:
            # min distance along that direction
            res.append((min(gf,bw)))
    return res
