import os,glob,re
def load2(fp):
    t=open(fp).read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
        else:
            # try single-row list format [a,b,c] style: find list after header even with spaces
            rem=t[m.end():]
            j=rem.find('[')
            seg=rem[j:j+250]
            nums=re.findall(r'\[\s*(\d+(?:,\s*\d+)*)\s*\]',seg)
            if nums:
                flat=[int(x) for x in nums[-1].split(',')]
                h=min(h,w)
                w_=len(flat)//h
                G[k]=([[flat[i*h+j_+1] for j_ in range(w_)], )]
    return G
for fp in sorted(glob.glob(base+'/sessions/*.jsonl')):
    g=load2(fp)
    ti=g.get('Test input')
    if isinstance(ti,list) and len(ti)>6 and any(isinstance(x,list) for x in ti):
        print(os.path.basename(fp), {k:len(v) for k,v in g.items()})

